.resume_versions\",\"created_at\",\"timestamp with time zone\",true],[\"public.resume_versions\",\"updated_at\",\"timestamp with time zone\",true],[\"private.retention_items\",\"id\",\"uuid\",true],[\"private.retention_items\",\"resume_id\",\"uuid\",true],[\"private.retention_items\",\"owner_id\",\"uuid\",true],[\"private.retention_items\",\"storage_key\",\"text\",true],[\"private.retention_items\",\"status\",\"text\",true],[\"private.retention_items\",\"attempt_count\",\"integer\",true],[\"private.retention_items\",\"last_error_code\",\"text\",false],[\"private.retention_items\",\"created_at\",\"timestamp with time zone\",true],[\"private.retention_items\",\"completed_at\",\"timestamp with time zone\",false]]$r17_source_columns$::jsonb) loop\n  if not exists(select 1 from pg_catalog.pg_attribute a join pg_catalog.pg_class c on c.oid=a.attrelid\n    where a.attrelid=to_regclass(item->>0) and a.attname=item->>1 and a.atttypid=to_regtype(item->>2) and a.attnotnull=(item->>3)::boolean\n      and a.attnum>0 and not a.attisdropped and c.relowner=owner_oid and c.relkind='r' and c.relrowsecurity)\n    then return false;end if;\n end loop;\n -- Diagnostic source + sealed Native forms; future actual application/transactions remain unexecuted.\n if private.ai_budget_source_ready() is not true then return false;end if;\n return true;\nexception when others then return false;\nend;\n","setof":false}]$source_patches$::jsonb;
begin
 for item in select value from jsonb_array_elements(manifest) loop
  select * into p from pg_catalog.pg_proc where oid=to_regprocedure(item->>'signature');
  if not found or p.prokind<>'f' or p.proretset or p.proisstrict or p.proconfig is distinct from array['search_path=""']
    or private.ifo_sha(p.prosrc)<>item->>'before' or p.prosrc is distinct from item->>'old' or private.ifo_sha(item->>'new')<>item->>'after'
    then raise exception 'AI_SOURCE_PREIMAGE_DRIFT' using errcode='23514';end if;
  source:=pg_get_functiondef(p.oid);
  if (length(source)-length(replace(source,p.prosrc,'')))/length(p.prosrc)<>1 then raise exception 'AI_SOURCE_DEFINITION_DRIFT' using errcode='23514';end if;
  statements:=array_append(statements,replace(source,p.prosrc,item->>'new'));
 end loop;
 foreach ddl in array statements loop execute ddl;end loop;
 for item in select value from jsonb_array_elements(manifest) loop
  if (select private.ifo_sha(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure(item->>'signature')) is distinct from item->>'after'
   then raise exception 'AI_SOURCE_POSTIMAGE_DRIFT' using errcode='23514';end if;
 end loop;
end;
$source_forward$;
